import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.BSwSpTvy.js";const f=JSON.parse('{"title":"👤 Agent Profiles","description":"","frontmatter":{},"headers":[],"relativePath":"features/agent-profiles.md","filePath":"features/agent-profiles.md"}'),s={name:"features/agent-profiles.md"};function r(n,e,l,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="👤-agent-profiles" tabindex="-1">👤 Agent Profiles <a class="header-anchor" href="#👤-agent-profiles" aria-label="Permalink to &quot;👤 Agent Profiles&quot;">​</a></h1><p>Zed Custom includes powerful <strong>Agent Profiles</strong>, a highly requested feature that allows you to configure specific environments, capabilities, and system prompts tailored for different tasks.</p><h2 id="managing-profiles" tabindex="-1">Managing Profiles <a class="header-anchor" href="#managing-profiles" aria-label="Permalink to &quot;Managing Profiles&quot;">​</a></h2><p>In the assistant panel, you can now view a list of default profiles and any custom profiles you create. You can switch between profiles, creating individual threads where the chosen profile has full context and capability for your specialized task.</p><p>To access the profile settings, click on the <strong>Settings (gear)</strong> icon inside the Assistant panel. Or, click the profile dropdown at the top of an Assistant thread to quickly select a profile.</p><p>You&#39;ll find your different Agent Profiles populated right in your <code>settings.json</code>, and can be manipulated via GUI natively inside Zed.</p><h2 id="what-is-configurable" tabindex="-1">What is configurable? <a class="header-anchor" href="#what-is-configurable" aria-label="Permalink to &quot;What is configurable?&quot;">​</a></h2><p>You can configure several options inside every individual Agent Profile to give it a unique set of abilities and behaviors.</p><h3 id="_1-model-selection" tabindex="-1">1. Model Selection <a class="header-anchor" href="#_1-model-selection" aria-label="Permalink to &quot;1. Model Selection&quot;">​</a></h3><p>Assign a specific Default LLM to a given agent profile. Do you need a coding profile that defaults to Claude 3.7 Sonnet? Or a rapid question-answering profile that defaults to Claude 3.5 Haiku? Pick it once and the Agent Profile will always start with it.</p><h3 id="_2-available-tools" tabindex="-1">2. Available Tools <a class="header-anchor" href="#_2-available-tools" aria-label="Permalink to &quot;2. Available Tools&quot;">​</a></h3><p>You can selectively enable or disable tools for each profile. For instance, you could configure a &quot;Web Researcher&quot; profile that only has access to the <code>/search</code> and <code>/fetch</code> tools, so it doesn&#39;t accidentally attempt to read or write local project files.</p><h3 id="_3-context-servers" tabindex="-1">3. Context Servers <a class="header-anchor" href="#_3-context-servers" aria-label="Permalink to &quot;3. Context Servers&quot;">​</a></h3><p>Integrate with different MCP (Model Context Protocol) servers on a per-profile basis! If you have multiple custom servers available, you can turn them on specifically for an Agent Profile designed simply to query your company&#39;s API.</p><h3 id="_4-custom-instructions-system-prompts" tabindex="-1">4. Custom Instructions &amp; System Prompts <a class="header-anchor" href="#_4-custom-instructions-system-prompts" aria-label="Permalink to &quot;4. Custom Instructions &amp; System Prompts&quot;">​</a></h3><p>You can specify:</p><ul><li><strong>Instructions</strong>: Snippets of rules or behavioral adjustments appended to the base Zed system prompt (for example: &quot;Always use TailwindCSS&quot;).</li><li><strong>System Prompts</strong>: Complete overwrites of the default Zed AI system prompt. Build an entirely distinct character or specialized engineer persona.</li></ul><h2 id="configuring-profiles-via-ui-vs-settings" tabindex="-1">Configuring profiles via UI vs Settings <a class="header-anchor" href="#configuring-profiles-via-ui-vs-settings" aria-label="Permalink to &quot;Configuring profiles via UI vs Settings&quot;">​</a></h2><p>You can use the new Configuration Modal inside the Assistant panel to modify your current profile, create a new profile from an existing one, or start from scratch!</p><p>Changes executed via the UI are instantly serialized into your workspace&#39;s <code>settings.json</code> file.</p>',20)])])}const h=t(s,[["render",r]]);export{f as __pageData,h as default};
